//! Unit tests for hook ownership classification (`ownership.rs`).

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::fs;
use std::path::{Path, PathBuf};

use super::*;
use crate::hook_script::MARKER;
use crate::hooks::install;

/// A wrapper in the shape `pre-commit install` writes.
const WRAPPER: &str = "#!/usr/bin/env bash\n\
# File generated by pre-commit: https://pre-commit.com\n\
INSTALL_PYTHON=/usr/bin/python3\n\
exec \"$INSTALL_PYTHON\" -m pre_commit hook-install --hook-type=pre-commit\n";

/// An unmarked hook written by hand or by another manager.
const FOREIGN: &str = "#!/usr/bin/env bash\nexec ./scripts/lint.sh\n";

fn git_repo() -> (tempfile::TempDir, PathBuf) {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().to_path_buf();
    let status = crate::changes::git_command(&root)
        .args(["init", "-q"])
        .status()
        .unwrap();
    assert!(status.success());
    fs::create_dir_all(root.join(".git/hooks")).unwrap();
    (temp, root)
}

fn hook_file(root: &Path, name: &str, content: &str) -> PathBuf {
    let path = root.join(".git/hooks").join(name);
    fs::write(&path, content).unwrap();
    path
}

#[test]
fn absent_when_no_hook_file_exists() {
    let (_temp, root) = git_repo();
    let path = root.join(".git/hooks/pre-commit");

    assert_eq!(classify(&path, false, false), HookOwner::Absent);
    assert_eq!(classify(&path, true, true), HookOwner::Absent);
}

#[test]
fn managed_marker_wins_over_a_pre_commit_configuration() {
    let (_temp, root) = git_repo();
    let path = hook_file(
        &root,
        "pre-commit",
        "#!/usr/bin/env bash\n# do-harness-hook v1\n",
    );

    assert_eq!(classify(&path, true, false), HookOwner::Managed);
}

#[test]
fn pre_commit_wrapper_is_recognised_without_a_configuration() {
    let (_temp, root) = git_repo();
    let path = hook_file(&root, "pre-commit", WRAPPER);

    assert_eq!(classify(&path, false, false), HookOwner::PreCommit);
    assert!(is_pre_commit_wrapper(WRAPPER));
    assert!(!is_pre_commit_wrapper(FOREIGN));
}

#[test]
fn pre_commit_configuration_owns_a_rewritten_wrapper() {
    let (_temp, root) = git_repo();
    let path = hook_file(&root, "commit-msg", FOREIGN);

    assert_eq!(classify(&path, true, false), HookOwner::PreCommit);
}

#[test]
fn custom_hooks_path_owns_a_foreign_hook() {
    let (_temp, root) = git_repo();
    let path = hook_file(&root, "pre-push", FOREIGN);

    assert_eq!(classify(&path, false, true), HookOwner::HooksPath);
}

#[test]
fn unowned_foreign_hook_is_not_attributed_to_anyone() {
    let (_temp, root) = git_repo();
    let path = hook_file(&root, "pre-push", FOREIGN);

    assert_eq!(classify(&path, false, false), HookOwner::Foreign);
}

#[test]
fn satisfied_covers_managed_and_delegated_hooks_only() {
    let ownership = |owner| HookOwnership {
        pre_commit: owner,
        pre_push: owner,
        commit_msg: owner,
    };

    assert!(ownership(HookOwner::Managed).is_satisfied());
    assert!(ownership(HookOwner::PreCommit).is_satisfied());
    assert!(ownership(HookOwner::HooksPath).is_satisfied());
    assert!(!ownership(HookOwner::Absent).is_satisfied());
    assert!(!ownership(HookOwner::Foreign).is_satisfied());
    assert_eq!(HookOwner::PreCommit.as_str(), "delegated_pre_commit");
    assert_eq!(HookOwner::HooksPath.as_str(), "delegated_hooks_path");
}

/// The destructive half of delegation: a plain `hook install` must name the
/// framework it would replace and leave the wrapper in place.
#[test]
fn install_refuses_to_replace_a_pre_commit_wrapper() {
    let (temp, root) = git_repo();
    let git_dir = root.join(".git");
    let wrapper = hook_file(&root, "pre-commit", WRAPPER);

    let err = install(&git_dir, temp.path(), &[], &[], false).unwrap_err();

    let message = err.to_string();
    assert!(message.contains("pre-commit framework"), "{message}");
    assert!(message.contains("--force"), "{message}");
    assert_eq!(fs::read_to_string(&wrapper).unwrap(), WRAPPER);
    assert!(!root.join(".git/hooks/pre-push").exists());
}

/// `--force` is the documented escape hatch for taking the hooks over.
#[test]
fn install_force_replaces_a_pre_commit_wrapper() {
    let (temp, root) = git_repo();
    let git_dir = root.join(".git");
    let wrapper = hook_file(&root, "pre-commit", WRAPPER);

    install(&git_dir, temp.path(), &[], &[], true).unwrap();

    assert!(fs::read_to_string(&wrapper).unwrap().contains(MARKER));
}
